window.FIG_SERIES=window.FIG_SERIES||{};window.FIG_SERIES["FIG-69d5065fb1ea5a3b"]={"versions": [{"id": "FIG-69d5065fb1ea5a3b", "releases": ["R4.1.3"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Protokoll- und Frame-Layout-Diagramm. Die Abbildung spezifiziert die exakte Bit- und Byte-Struktur eines „Type 2 Entry“ (Eintrag für Eventgroups) im SOME/IP-Service-Discovery-Protokoll (AUTOSAR_SWS_ServiceDiscovery) über ein 32-Bit-Raster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine 16-Byte-Datenstruktur (vier 32-Bit-Wörter):</p>\n<ul class=\"fig-list\"><li><strong>Wort 1 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Type</code> (Bit 0–7, 8 Bit): Kennung des Eintragstyps (Typ 2 für Eventgroups).\n</li><li><code>Index 1st options</code> (Bit 8–15, 8 Bit): Index der ersten referenzierten Option im Options-Array.\n</li><li><code>Index 2nd options</code> (Bit 16–23, 8 Bit): Index der zweiten referenzierten Option im Options-Array.\n</li><li><code># of opt 1</code> (Bit 24–27, 4 Bit): Anzahl der Optionen im ersten Optionslauf.\n</li><li><code># of opt 2</code> (Bit 28–31, 4 Bit): Anzahl der Optionen im zweiten Optionslauf.\n</li></ul>\n</li><li><strong>Wort 2 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Service ID</code> (Bit 0–15, 16 Bit): Kennung des angebotenen bzw. angefragten Dienstes.\n</li><li><code>Instance ID</code> (Bit 16–31, 16 Bit): Instanzkennung des Dienstes.\n</li></ul>\n</li><li><strong>Wort 3 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Major Version</code> (Bit 0–7, 8 Bit): Hauptversionsnummer des Dienstes.\n</li><li><code>TTL</code> (Bit 8–31, 24 Bit): Time to Live des Eintrags in Sekunden.\n</li></ul>\n</li><li><strong>Wort 4 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Reserved (0x0000)</code> (Bit 0–15, 16 Bit): Reserviertes Feld mit festem Wert <code>0x0000</code>.\n</li><li><code>Eventgroup ID</code> (Bit 16–31, 16 Bit): Kennung der spezifischen Eventgroup innerhalb des Dienstes.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Definition des Serialisierungsformats für Eventgroup-Einträge. Die Struktur wird im Rahmen von SOME/IP-SD-Nachrichten (z. B. Find-, Offer- oder Subscribe-Eventgroup-Nachrichten) im Entry-Array übertragen. Die Auswertung erfolgt sequenziell in 32-Bit-Schritten von Big-Endian-kodierten Feldern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Serialisierung und Deserialisierung von Type-2-Einträgen:</p>\n<ul class=\"fig-list\"><li>Die Bitgrenzen und Feldbreiten müssen strikt eingehalten werden (Gesamtlänge 128 Bit bzw. 16 Oktette).\n</li><li>Das Feld <code>Reserved (0x0000)</code> ist auf allen 16 Bits mit Nullen zu belegen und empfängerseitig entsprechend zu verarbeiten bzw. zu ignorieren.\n</li><li>Die Referenzierung von Optionen erfolgt über die 8-Bit-Indizes und 4-Bit-Längenangaben im ersten Wort.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d896d62f4a61e205", "releases": ["R4.2.2"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Protokoll- und Frame-Layout-Diagramm. Die Abbildung spezifiziert die exakte Bit- und Byte-Struktur eines „Type 2 Entry“ (Eintrag für Eventgroups) im SOME/IP-Service-Discovery-Protokoll (AUTOSAR_SWS_ServiceDiscovery) über ein 32-Bit-Raster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine 16-Byte-Datenstruktur (vier 32-Bit-Wörter):</p>\n<ul class=\"fig-list\"><li><strong>Wort 1 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Type</code> (Bit 0–7, 8 Bit): Kennung des Eintragstyps (Typ 2 für Eventgroups).\n</li><li><code>Index 1st options</code> (Bit 8–15, 8 Bit): Index der ersten referenzierten Option im Options-Array.\n</li><li><code>Index 2nd options</code> (Bit 16–23, 8 Bit): Index der zweiten referenzierten Option im Options-Array.\n</li><li><code># of opt 1</code> (Bit 24–27, 4 Bit): Anzahl der Optionen im ersten Optionslauf.\n</li><li><code># of opt 2</code> (Bit 28–31, 4 Bit): Anzahl der Optionen im zweiten Optionslauf.\n</li></ul>\n</li><li><strong>Wort 2 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Service ID</code> (Bit 0–15, 16 Bit): Kennung des angebotenen bzw. angefragten Dienstes.\n</li><li><code>Instance ID</code> (Bit 16–31, 16 Bit): Instanzkennung des Dienstes.\n</li></ul>\n</li><li><strong>Wort 3 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Major Version</code> (Bit 0–7, 8 Bit): Hauptversionsnummer des Dienstes.\n</li><li><code>TTL</code> (Bit 8–31, 24 Bit): Time to Live des Eintrags in Sekunden.\n</li></ul>\n</li><li><strong>Wort 4 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Reserved (0x000)</code> (Bit 0–11, 12 Bit): Reserviertes Feld mit festem Wert <code>0x000</code>.\n</li><li><code>Counter</code> (Bit 12–15, 4 Bit): 4-Bit-Zählerfeld.\n</li><li><code>Eventgroup ID</code> (Bit 16–31, 16 Bit): Kennung der spezifischen Eventgroup innerhalb des Dienstes.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Definition des Serialisierungsformats für Eventgroup-Einträge. Die Struktur wird im Rahmen von SOME/IP-SD-Nachrichten (z. B. Find-, Offer- oder Subscribe-Eventgroup-Nachrichten) im Entry-Array übertragen. Die Auswertung erfolgt sequenziell in 32-Bit-Schritten von Big-Endian-kodierten Feldern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Serialisierung und Deserialisierung von Type-2-Einträgen:</p>\n<ul class=\"fig-list\"><li>Die Bitgrenzen und Feldbreiten müssen strikt eingehalten werden (Gesamtlänge 128 Bit bzw. 16 Oktette).\n</li><li>Das Feld <code>Reserved (0x000)</code> umfasst exakt 12 Bit und ist mit Nullen zu belegen.\n</li><li>Das 4 Bit breite Feld <code>Counter</code> belegt die Bits 12 bis 15 des vierten Wortes.\n</li><li>Die Referenzierung von Optionen erfolgt über die 8-Bit-Indizes und 4-Bit-Längenangaben im ersten Wort.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-7016a4a39355aa94", "releases": ["R4.3.1", "R18-10_R4.4.0_R1.5.0", "R19-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Protokoll- und Frame-Layout-Diagramm. Die Abbildung spezifiziert die exakte Bit- und Byte-Struktur eines „Type 2 Entry“ (Eintrag für Eventgroups) im SOME/IP-Service-Discovery-Protokoll (AUTOSAR_SWS_ServiceDiscovery) über ein 32-Bit-Raster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine 16-Byte-Datenstruktur (vier 32-Bit-Wörter):</p>\n<ul class=\"fig-list\"><li><strong>Wort 1 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Type</code> (Bit 0–7, 8 Bit): Kennung des Eintragstyps (Typ 2 für Eventgroups).\n</li><li><code>Index 1st options</code> (Bit 8–15, 8 Bit): Index der ersten referenzierten Option im Options-Array.\n</li><li><code>Index 2nd options</code> (Bit 16–23, 8 Bit): Index der zweiten referenzierten Option im Options-Array.\n</li><li><code># of opt 1</code> (Bit 24–27, 4 Bit): Anzahl der Optionen im ersten Optionslauf.\n</li><li><code># of opt 2</code> (Bit 28–31, 4 Bit): Anzahl der Optionen im zweiten Optionslauf.\n</li></ul>\n</li><li><strong>Wort 2 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Service ID</code> (Bit 0–15, 16 Bit): Kennung des angebotenen bzw. angefragten Dienstes.\n</li><li><code>Instance ID</code> (Bit 16–31, 16 Bit): Instanzkennung des Dienstes.\n</li></ul>\n</li><li><strong>Wort 3 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Major Version</code> (Bit 0–7, 8 Bit): Hauptversionsnummer des Dienstes.\n</li><li><code>TTL</code> (Bit 8–31, 24 Bit): Time to Live des Eintrags in Sekunden.\n</li></ul>\n</li><li><strong>Wort 4 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Reserved (0x000)</code> (Bit 0–11, 12 Bit): Reserviertes Feld mit festem Wert <code>0x000</code>.\n</li><li><code>Counter</code> (Bit 12–15, 4 Bit): 4-Bit-Zählerfeld.\n</li><li><code>Eventgroup ID</code> (Bit 16–31, 16 Bit): Kennung der spezifischen Eventgroup innerhalb des Dienstes.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Definition des Serialisierungsformats für Eventgroup-Einträge. Die Struktur wird im Rahmen von SOME/IP-SD-Nachrichten (z. B. Find-, Offer- oder Subscribe-Eventgroup-Nachrichten) im Entry-Array übertragen. Die Auswertung erfolgt sequenziell in 32-Bit-Schritten von Big-Endian-kodierten Feldern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Serialisierung und Deserialisierung von Type-2-Einträgen:</p>\n<ul class=\"fig-list\"><li>Die Bitgrenzen und Feldbreiten müssen strikt eingehalten werden (Gesamtlänge 128 Bit bzw. 16 Oktette).\n</li><li>Das Feld <code>Reserved (0x000)</code> umfasst exakt 12 Bit und ist mit Nullen zu belegen.\n</li><li>Das 4 Bit breite Feld <code>Counter</code> belegt die Bits 12 bis 15 des vierten Wortes.\n</li><li>Die Referenzierung von Optionen erfolgt über die 8-Bit-Indizes und 4-Bit-Längenangaben im ersten Wort.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}, {"id": "FIG-d5b82778a20d07d6", "releases": ["R20-11"], "html": "<h4 class=\"fig-section-h4\">1. Diagrammtyp &amp; Architektur-Kontext</h4>\n<p class=\"fig-p\">Binäres Protokoll- und Frame-Layout-Diagramm. Die Abbildung spezifiziert die exakte Bit- und Byte-Struktur eines „Type 2 Entry“ (Eintrag für Eventgroups) im SOME/IP-Service-Discovery-Protokoll (AUTOSAR_SWS_ServiceDiscovery) über ein 32-Bit-Raster.</p>\n<h4 class=\"fig-section-h4\">2. Komponenten, Entitäten &amp; Schnittstellen</h4>\n<p class=\"fig-p\">Das Diagramm definiert eine 16-Byte-Datenstruktur (vier 32-Bit-Wörter):</p>\n<ul class=\"fig-list\"><li><strong>Wort 1 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Type</code> (Bit 0–7, 8 Bit): Kennung des Eintragstyps (Typ 2 für Eventgroups).\n</li><li><code>Index 1st options</code> (Bit 8–15, 8 Bit): Index der ersten referenzierten Option im Options-Array.\n</li><li><code>Index 2nd options</code> (Bit 16–23, 8 Bit): Index der zweiten referenzierten Option im Options-Array.\n</li><li><code># of opt 1</code> (Bit 24–27, 4 Bit): Anzahl der Optionen im ersten Optionslauf.\n</li><li><code># of opt 2</code> (Bit 28–31, 4 Bit): Anzahl der Optionen im zweiten Optionslauf.\n</li></ul>\n</li><li><strong>Wort 2 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Service ID</code> (Bit 0–15, 16 Bit): Kennung des angebotenen bzw. angefragten Dienstes.\n</li><li><code>Instance ID</code> (Bit 16–31, 16 Bit): Instanzkennung des Dienstes.\n</li></ul>\n</li><li><strong>Wort 3 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Major Version</code> (Bit 0–7, 8 Bit): Hauptversionsnummer des Dienstes.\n</li><li><code>TTL</code> (Bit 8–31, 24 Bit): Time to Live des Eintrags in Sekunden.\n</li></ul>\n</li><li><strong>Wort 4 (Bit 0–31):</strong>\n<ul class=\"fig-list\"><li><code>Reserved (0x000)</code> (Bit 0–11, 12 Bit): Reserviertes Feld mit festem Wert <code>0x000</code>.\n</li><li><code>Counter</code> (Bit 12–15, 4 Bit): 4-Bit-Zählerfeld.\n</li><li><code>Eventgroup ID</code> (Bit 16–31, 16 Bit): Kennung der spezifischen Eventgroup innerhalb des Dienstes.\n</li></ul>\n</li></ul>\n<h4 class=\"fig-section-h4\">3. Dynamisches Verhalten &amp; Sequenzablauf</h4>\n<p class=\"fig-p\">Statische Definition des Serialisierungsformats für Eventgroup-Einträge. Die Struktur wird im Rahmen von SOME/IP-SD-Nachrichten (z. B. Find-, Offer- oder Subscribe-Eventgroup-Nachrichten) im Entry-Array übertragen. Die Auswertung erfolgt sequenziell in 32-Bit-Schritten von Big-Endian-kodierten Feldern.</p>\n<h4 class=\"fig-section-h4\">4. Normative Relevanz &amp; Entwickler-Hinweise</h4>\n<p class=\"fig-p\">Normative Vorgabe für die Serialisierung und Deserialisierung von Type-2-Einträgen:</p>\n<ul class=\"fig-list\"><li>Die Bitgrenzen und Feldbreiten müssen strikt eingehalten werden (Gesamtlänge 128 Bit bzw. 16 Oktette).\n</li><li>Das Feld <code>Reserved (0x000)</code> umfasst exakt 12 Bit und ist mit Nullen zu belegen.\n</li><li>Das 4 Bit breite Feld <code>Counter</code> belegt die Bits 12 bis 15 des vierten Wortes.\n</li><li>Die Referenzierung von Optionen erfolgt über die 8-Bit-Indizes und 4-Bit-Längenangaben im ersten Wort.\n</li></ul>", "model": "gemini-3.8-flash (via agy)"}], "trans": [{"from": "FIG-69d5065fb1ea5a3b", "to": "FIG-d896d62f4a61e205", "fr": "R4.1.3", "tr": "R4.2.2", "change": "normativ", "label": "normative Änderung", "html": "<ul class=\"fig-list\"><li>Die vierte 32-Bit-Zeile wird strukturell neu aufgeteilt: Das bisher 16 Bit breite Feld <code>Reserved (0x0000)</code> (Bit 0 bis 15) wird durch ein 12 Bit breites Feld <code>Reserved (0x000)</code> (Bit 0 bis 11) und ein neu eingeführtes 4 Bit breites Feld <code>Counter</code> (Bit 12 bis 15) ersetzt.\n</li><li>Das Feld <code>Eventgroup ID</code> verbleibt unverändert auf Bit 16 bis 31.\n</li></ul>"}, {"from": "FIG-d896d62f4a61e205", "to": "FIG-7016a4a39355aa94", "fr": "R4.2.2", "tr": "R4.3.1", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}, {"from": "FIG-7016a4a39355aa94", "to": "FIG-d5b82778a20d07d6", "fr": "R19-11", "tr": "R20-11", "change": "keine", "label": "keine inhaltliche Änderung", "html": "<p class=\"fig-p\">Keine inhaltlichen Änderungen erkennbar.</p>"}]};
